2	const $app = document.getElementById('app');
3	const $count = document.getElementById('cart-count');
4	const fmt = (n) => '$' + Number(n).toFixed(2);
5	const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
